-- | JSON values for the protocol. The parser is generated by peg-hs from
-- the JSON grammar of the conformance tests (@grammar/Json.peg@, ADR 0035).
--
-- 'parseJson' and 'renderJson' convert between text and t'Value'. The
-- accessors return 'Nothing' for a value of another shape, so that a
-- field is read in the 'Maybe' monad:
--
-- @
-- uri :: Value -> Maybe Text
-- uri msg = path [\"params\", \"textDocument\", \"uri\"] msg >>= asText
--
-- reply :: Value
-- reply = object [(\"jsonrpc\", String \"2.0\"), (\"id\", int 1), (\"result\", Null)]
-- @
module Peg.Lsp.Json
  ( Value (..)
  , parseJson
  , renderJson
  , member
  , path
  , asText
  , asInt
  , asBool
  , asArray
  , int
  , object
  ) where

import Data.Char (ord)
import Data.Text (Text)
import qualified Data.Text as T
import qualified Data.Text.Lazy as TL
import qualified Data.Text.Lazy.Builder as B
import Numeric (showHex)
import Peg.Lsp.JsonParser (Value (..), parse)
import Text.Read (readMaybe)

-- | Parse a JSON text. 'Nothing' if it is not JSON.
parseJson :: Text -> Maybe Value
parseJson = either (const Nothing) Just . parse

-- | Render a value as compact JSON. A number is written as its lexeme.
renderJson :: Value -> Text
renderJson = TL.toStrict . B.toLazyText . go
  where
    go = \case
      Null -> "null"
      Bool True -> "true"
      Bool False -> "false"
      Number n -> B.fromText n
      String s -> string s
      Array vs -> "[" <> commas (map go vs) <> "]"
      Object ms -> "{" <> commas [string k <> ":" <> go v | (k, v) <- ms] <> "}"
    commas [] = mempty
    commas (x : xs) = x <> mconcat (map ("," <>) xs)
    string s = "\"" <> T.foldr (\c b -> escape c <> b) mempty s <> "\""
    escape = \case
      '"' -> "\\\""
      '\\' -> "\\\\"
      '\n' -> "\\n"
      '\r' -> "\\r"
      '\t' -> "\\t"
      c
        | ord c < 0x20 -> B.fromString ("\\u" <> replicate (4 - length (showHex (ord c) "")) '0' <> showHex (ord c) "")
        | otherwise -> B.singleton c

-- | A member of an object; the last one of a name given twice.
member :: Text -> Value -> Maybe Value
member k = \case
  Object ms -> lookup k (reverse ms)
  _ -> Nothing

-- | Members of members: @path [\"a\", \"b\"]@ is the member @b@ of the
-- member @a@.
path :: [Text] -> Value -> Maybe Value
path ks v = foldl (\m k -> m >>= member k) (Just v) ks

-- | A string.
asText :: Value -> Maybe Text
asText = \case
  String s -> Just s
  _ -> Nothing

-- | An integer, written without a fraction or an exponent.
asInt :: Value -> Maybe Int
asInt = \case
  Number n -> readMaybe (T.unpack n)
  _ -> Nothing

-- | A boolean.
asBool :: Value -> Maybe Bool
asBool = \case
  Bool b -> Just b
  _ -> Nothing

-- | The elements of an array.
asArray :: Value -> Maybe [Value]
asArray = \case
  Array vs -> Just vs
  _ -> Nothing

-- | A number from an integer.
int :: Int -> Value
int = Number . T.pack . show

-- | An object with the members in the given order.
object :: [(Text, Value)] -> Value
object = Object
